"""Lightweight, opt-out-able analytics with switchable providers."""

import atexit
import os
import platform
import re
import sys
import threading
import uuid
from pathlib import Path

import requests

from cli_hub import __version__

ANALYTICS_PROVIDER = "posthog"
UMAMI_URL = "https://cloud.umami.is/api/send"
UMAMI_WEBSITE_ID = "a076c661-bed1-405c-a522-813794e688b4"
POSTHOG_API_HOST = "https://us.i.posthog.com"
POSTHOG_PROJECT_TOKEN = "phc_ovP8d5bmjpn8YZnTo7pb6rE3TikcAMgmNVt75o3Ywejz"
HOSTNAME = "clianything.cc"
USER_AGENT = f"Mozilla/5.0 (compatible; cli-anything-hub/{__version__})"
ANALYTICS_ID_FILE = ".analytics_id"

_pending_threads = []
_lock = threading.Lock()

_AGENT_ENV_RULES = (
    ("CLAUDE_CODE", "agent_tool", "claude-code-env"),
    ("CLAUDECODE", "agent_tool", "claude-code-env-alt"),
    ("CODEX", "agent_tool", "codex-env"),
    ("OPENAI_CODEX", "agent_tool", "codex-env-alt"),
    ("CURSOR_SESSION", "agent_tool", "cursor-session-env"),
    ("CURSOR_TRACE_ID", "agent_tool", "cursor-trace-env"),
    ("CLINE_SESSION", "agent_tool", "cline-session-env"),
    ("AIDER", "agent_tool", "aider-env"),
    ("AIDER_SESSION_ID", "agent_tool", "aider-session-env"),
    ("CONTINUE_SESSION", "agent_tool", "continue-session-env"),
    ("OPENHANDS_AGENT", "agent_tool", "openhands-agent-env"),
    ("OPENHANDS_RUNTIME", "agent_tool", "openhands-runtime-env"),
    ("BROWSER_USE", "agent_tool", "browser-use-env"),
    ("STAGEHAND", "agent_tool", "stagehand-env"),
    ("GOOSE_AGENT", "agent_tool", "goose-agent-env"),
    ("ROO_CODE", "agent_tool", "roo-code-env"),
    ("WINDSURF_AGENT", "agent_tool", "windsurf-agent-env"),
)

_PARENT_PROCESS_RULES = (
    ("claude-code-process", "agent_tool", re.compile(r"\bclaude(?:[ -]?code)?\b", re.IGNORECASE)),
    ("codex-process", "agent_tool", re.compile(r"\bcodex(?:-cli)?\b", re.IGNORECASE)),
    ("copilot-process", "agent_tool", re.compile(r"\bcopilot(?:-cli)?\b", re.IGNORECASE)),
    ("cursor-process", "agent_tool", re.compile(r"\bcursor\b", re.IGNORECASE)),
    ("cline-process", "agent_tool", re.compile(r"\bcline\b", re.IGNORECASE)),
    ("aider-process", "agent_tool", re.compile(r"\baider\b", re.IGNORECASE)),
    ("continue-process", "agent_tool", re.compile(r"\bcontinue\b", re.IGNORECASE)),
    ("gemini-process", "agent_tool", re.compile(r"\bgemini(?:-cli)?\b", re.IGNORECASE)),
    ("auggie-process", "agent_tool", re.compile(r"\bauggie(?:-cli)?\b", re.IGNORECASE)),
    ("augment-process", "agent_tool", re.compile(r"\baugment(?:[ -]?agent)?\b", re.IGNORECASE)),
    ("amp-process", "agent_tool", re.compile(r"\bamp(?:code)?\b", re.IGNORECASE)),
    ("opencode-process", "agent_tool", re.compile(r"\bopencode\b", re.IGNORECASE)),
    ("kilo-process", "agent_tool", re.compile(r"\bkilo(?:code)?\b", re.IGNORECASE)),
    ("qodo-process", "agent_tool", re.compile(r"\bqodo\b", re.IGNORECASE)),
    ("kiro-process", "agent_tool", re.compile(r"\bkiro\b", re.IGNORECASE)),
    ("openhands-process", "agent_tool", re.compile(r"\bopenhands\b", re.IGNORECASE)),
    ("browser-use-process", "agent_tool", re.compile(r"\bbrowser[- ]use\b", re.IGNORECASE)),
    ("stagehand-process", "agent_tool", re.compile(r"\bstagehand\b", re.IGNORECASE)),
    ("roo-process", "agent_tool", re.compile(r"\broo(?:-code)?\b", re.IGNORECASE)),
    ("windsurf-process", "agent_tool", re.compile(r"\bwindsurf\b", re.IGNORECASE)),
    ("goose-process", "agent_tool", re.compile(r"\bgoose\b", re.IGNORECASE)),
)


def _flush_pending():
    """Wait for in-flight analytics requests before process exit."""
    with _lock:
        threads = list(_pending_threads)
    for t in threads:
        t.join(timeout=3)


atexit.register(_flush_pending)


def _is_enabled():
    return os.environ.get("CLI_HUB_NO_ANALYTICS", "").strip() not in ("1", "true", "yes")


def _provider():
    provider = os.environ.get("CLI_HUB_ANALYTICS_PROVIDER", ANALYTICS_PROVIDER).strip().lower()
    return provider if provider in {"posthog", "umami"} else ANALYTICS_PROVIDER


def _analytics_dir():
    return Path.home() / ".cli-hub"


def _stdin_is_tty():
    try:
        return sys.stdin.isatty()
    except Exception:
        return False


def _read_parent_pid(pid):
    status_path = Path("/proc") / str(pid) / "status"
    try:
        for line in status_path.read_text().splitlines():
            if line.startswith("PPid:"):
                parts = line.split()
                return int(parts[1]) if len(parts) > 1 else None
    except Exception:
        return None
    return None


def _read_process_cmdline(pid):
    cmdline_path = Path("/proc") / str(pid) / "cmdline"
    try:
        raw = cmdline_path.read_bytes()
    except Exception:
        return ""
    return raw.replace(b"\x00", b" ").decode("utf-8", errors="ignore").strip()


def _parent_process_commands(max_depth=4):
    commands = []
    pid = os.getpid()
    for _ in range(max_depth):
        pid = _read_parent_pid(pid)
        if not pid or pid <= 1:
            break
        cmd = _read_process_cmdline(pid)
        if cmd:
            commands.append(cmd)
    return commands


def detect_invocation_context():
    """Classify the current cli-hub invocation as human, agent, or scripted."""
    signals = []

    for env_name, category, signal_id in _AGENT_ENV_RULES:
        if os.environ.get(env_name):
            signals.append({"id": signal_id, "category": category})

    for cmd in _parent_process_commands():
        for signal_id, category, pattern in _PARENT_PROCESS_RULES:
            if pattern.search(cmd):
                signals.append({"id": signal_id, "category": category})

    seen = set()
    unique_signals = []
    for signal in signals:
        if signal["id"] in seen:
            continue
        seen.add(signal["id"])
        unique_signals.append(signal)

    stdin_tty = _stdin_is_tty()
    if unique_signals:
        primary = unique_signals[0]
        return {
            "is_agent": True,
            "traffic_type": "agent",
            "category": primary["category"],
            "reason": primary["id"],
            "signals": [signal["id"] for signal in unique_signals],
            "stdin_tty": stdin_tty,
            "is_interactive": stdin_tty,
        }

    if not stdin_tty:
        return {
            "is_agent": True,
            "traffic_type": "agent",
            "category": "scripted_client",
            "reason": "stdin-not-tty",
            "signals": ["stdin-not-tty"],
            "stdin_tty": False,
            "is_interactive": False,
        }

    return {
        "is_agent": False,
        "traffic_type": "human",
        "category": "human",
        "reason": "human",
        "signals": [],
        "stdin_tty": True,
        "is_interactive": True,
    }


def _get_distinct_id():
    override = os.environ.get("CLI_HUB_ANALYTICS_DISTINCT_ID", "").strip()
    if override:
        return override

    marker = _analytics_dir() / ANALYTICS_ID_FILE
    try:
        if marker.exists():
            value = marker.read_text().strip()
            if value:
                return value
        marker.parent.mkdir(parents=True, exist_ok=True)
        value = str(uuid.uuid4())
        marker.write_text(value)
        return value
    except Exception:
        return f"cli-hub-anon-{uuid.uuid4()}"


def _posthog_capture_url():
    host = os.environ.get("CLI_HUB_POSTHOG_API_HOST", POSTHOG_API_HOST).rstrip("/")
    return f"{host}/capture/"


def _build_umami_payload(event_name, url, data):
    return {
        "type": "event",
        "payload": {
            "website": UMAMI_WEBSITE_ID,
            "hostname": HOSTNAME,
            "url": url,
            "name": event_name,
            "data": data,
        },
    }


def _build_posthog_payload(event_name, url, data):
    return {
        "api_key": os.environ.get("CLI_HUB_POSTHOG_PROJECT_TOKEN", POSTHOG_PROJECT_TOKEN),
        "event": event_name,
        "distinct_id": _get_distinct_id(),
        "properties": {
            "$current_url": f"https://{HOSTNAME}{url}",
            "hostname": HOSTNAME,
            "source": "cli",
            "channel": "cli-hub",
            "hub_version": __version__,
            **(data or {}),
        },
    }


def _send_event(payload):
    """Send a single event payload. Blocking — callers should use threads."""
    try:
        if _provider() == "umami":
            return requests.post(
                UMAMI_URL,
                json=payload,
                timeout=5,
                headers={"User-Agent": USER_AGENT},
            )
        return requests.post(
            _posthog_capture_url(),
            json=payload,
            timeout=5,
            headers={"User-Agent": USER_AGENT},
        )
    except Exception:
        return None  # analytics must never break the user's workflow


def track_event(event_name, url="/cli-anything-hub", data=None):
    """Fire-and-forget event to the active provider. Non-blocking, never raises."""
    if not _is_enabled():
        return

    event_data = data or {}
    if _provider() == "umami":
        payload = _build_umami_payload(event_name, url, event_data)
    else:
        payload = _build_posthog_payload(event_name, url, event_data)

    t = threading.Thread(target=_send_event, args=(payload,), daemon=True)
    with _lock:
        _pending_threads.append(t)
    t.start()


def track_install(cli_name, version):
    """Track a CLI install event. CLI name goes in properties, not the event name,
    so the event catalog stays flat and dashboards can break down by properties.cli."""
    track_event("cli-install", url=f"/cli-anything-hub/install/{cli_name}", data={
        "cli": cli_name,
        "version": version,
        "platform": platform.system().lower(),
    })


def track_uninstall(cli_name):
    """Track a CLI uninstall event."""
    track_event("cli-uninstall", url=f"/cli-anything-hub/uninstall/{cli_name}", data={
        "cli": cli_name,
        "platform": platform.system().lower(),
    })


def track_launch(cli_name):
    """Track a CLI launch event — fires when a user runs `cli-hub launch <name>`.
    Distinct from install: this is actual usage signal."""
    track_event("cli-launch", url=f"/cli-anything-hub/launch/{cli_name}", data={
        "cli": cli_name,
        "platform": platform.system().lower(),
    })


def track_matrix_install(matrix_name, scope="full", status="ok",
                         installed=0, skipped=0, failed=0, dry_run=False):
    """Track a CLI-Matrix install. The headline conversion signal for matrices:
    which matrix, the install scope (capability/recipe/only/full), and the outcome.
    Matrix name and scope go in properties so the event catalog stays flat — dashboards
    break down by properties.matrix / properties.scope, mirroring track_install."""
    track_event("matrix-install", url=f"/cli-anything-hub/matrix/install/{matrix_name}", data={
        "matrix": matrix_name,
        "scope": scope,
        "status": status,
        "installed": installed,
        "skipped": skipped,
        "failed": failed,
        "dry_run": dry_run,
        "platform": platform.system().lower(),
    })


def track_matrix_preflight(matrix_name, scope="full", covered=0, capabilities=0, gaps=0):
    """Track a CLI-Matrix preflight (capability-coverage check) — consideration signal
    that precedes install. Captures how much of the matrix the environment already covers."""
    track_event("matrix-preflight", url=f"/cli-anything-hub/matrix/preflight/{matrix_name}", data={
        "matrix": matrix_name,
        "scope": scope,
        "covered": covered,
        "capabilities": capabilities,
        "gaps": gaps,
        "platform": platform.system().lower(),
    })


def track_matrix_discover(kind, query="", results=0):
    """Track CLI-Matrix discovery — `matrix list`, `matrix search`, `matrix recipes`,
    and `cli-hub can`. `kind` distinguishes the surface; `results` is the hit count."""
    track_event("matrix-discover", url="/cli-anything-hub/matrix/discover", data={
        "kind": kind,
        "query": (query or "")[:120],
        "results": results,
        "platform": platform.system().lower(),
    })


def track_matrix_info(matrix_name, kind="info"):
    """Track inspecting a single CLI-Matrix — `matrix info` and `matrix doctor`."""
    track_event("matrix-info", url=f"/cli-anything-hub/matrix/info/{matrix_name}", data={
        "matrix": matrix_name,
        "kind": kind,
        "platform": platform.system().lower(),
    })


def track_visit(is_agent=False, command="root", detection=None):
    """Track a cli-hub invocation using the new cli-hub call event."""
    stdin_tty = _stdin_is_tty()
    context = detection or {
        "is_agent": is_agent,
        "traffic_type": "agent" if is_agent else "human",
        "category": "legacy-agent" if is_agent else "human",
        "reason": "legacy-flag" if is_agent else "human",
        "signals": ["legacy-flag"] if is_agent else [],
        "stdin_tty": stdin_tty,
        "is_interactive": stdin_tty,
    }
    track_event("cli-hub call", url="/cli-anything-hub/call", data={
        "command": command,
        "is_agent": context["is_agent"],
        "traffic_type": context["traffic_type"],
        "agent_category": context["category"],
        "agent_reason": context["reason"],
        "agent_signals": context["signals"][:12],
        "stdin_tty": context["stdin_tty"],
        "is_interactive": context["is_interactive"],
        "platform": platform.system().lower(),
    })


def track_first_run():
    """Send a one-time 'cli-hub-installed' event on first invocation."""
    marker = _analytics_dir() / ".first_run_sent"
    if marker.exists():
        return
    track_event("cli-anything-hub-installed", url="/cli-anything-hub/installed", data={
        "version": __version__,
        "platform": platform.system().lower(),
    })
    try:
        marker.parent.mkdir(parents=True, exist_ok=True)
        marker.write_text(__version__)
    except Exception:
        pass


def _detect_is_agent():
    """Detect if cli-hub is likely being invoked by an AI agent."""
    return detect_invocation_context()["is_agent"]

"""cli-hub — CLI entry point."""

import os
import shutil
import sys
import json as json_mod
from pathlib import Path

import click

from cli_hub import __version__
from cli_hub.registry import fetch_all_clis, get_cli, search_clis, list_categories
from cli_hub.matrix import (
    all_recipes,
    capability_matches,
    fetch_all_matrices,
    get_matrix,
    get_recipe,
    preflight_matrix,
    provider_install_hint,
    search_capabilities,
    search_matrices,
)
from cli_hub.matrix_skill import get_rendered_matrix_skill_path, render_matrix_skill_file
from cli_hub.installer import (
    doctor_matrix,
    get_installed,
    install_cli,
    install_matrix,
    plan_matrix_install,
    uninstall_cli,
    update_cli,
)
from cli_hub.analytics import (
    detect_invocation_context,
    track_first_run,
    track_install,
    track_launch,
    track_matrix_discover,
    track_matrix_info,
    track_matrix_install,
    track_matrix_preflight,
    track_uninstall,
    track_visit,
)
from cli_hub.preview import (
    inspect_bundle,
    inspect_session,
    is_live_session_ref,
    load_session,
    open_in_browser,
    render_html,
    render_inspect_text,
    render_live_html,
    render_session_text,
    start_static_server,
)


# Exit-code contract for the matrix command family (F2.3 / F2.4):
#   0 success · 1 failure or not-found · 2 usage error · 3 partial / gaps
EXIT_OK = 0
EXIT_FAIL = 1
EXIT_USAGE = 2
EXIT_PARTIAL = 3


def _invocation_command(ctx, version):
    """Return a compact label for the current invocation."""
    argv = sys.argv[1:]
    if version:
        return "--version"
    if ctx.invoked_subcommand:
        return ctx.invoked_subcommand
    if any(arg in ("--help", "-h") for arg in argv):
        return "--help"
    if argv:
        return argv[0]
    return "root"


@click.group(invoke_without_command=True)
@click.option("--version", is_flag=True, help="Show version.")
@click.pass_context
def main(ctx, version):
    """cli-hub — Download and manage CLI-Anything CLIs, public CLIs, and curated matrices."""
    track_first_run()
    track_visit(command=_invocation_command(ctx, version), detection=detect_invocation_context())
    if version:
        click.echo(f"cli-hub {__version__}")
        return
    if ctx.invoked_subcommand is None:
        click.echo(ctx.get_help())


def _source_tag(cli):
    """Return a styled source indicator for display."""
    source = cli.get("_source", "harness")
    if source == "public":
        manager = cli.get("package_manager") or cli.get("install_strategy") or "public"
        return click.style(f" {manager}", fg="yellow")
    return ""


def _plural(count, singular, plural=None):
    """Return a compact count label with basic pluralization."""
    return f"{count} {singular if count == 1 else (plural or singular + 's')}"


@main.command()
@click.argument("name")
def install(name):
    """Install a CLI by name."""
    click.echo(f"Installing {name}...")
    success, msg = install_cli(name)
    if success:
        cli = get_cli(name)
        track_install(name, cli["version"] if cli else "unknown")
        click.secho(f"✓ {msg}", fg="green")
        if cli:
            click.echo(f"  Run it with: {cli['entry_point']}")
            click.echo(f"  Or launch:   cli-hub launch {cli['name']}")
            if cli.get("_source") == "public" and cli.get("npx_cmd"):
                click.echo(f"  Or use npx:  {cli['npx_cmd']}")
    else:
        click.secho(f"✗ {msg}", fg="red", err=True)
        raise SystemExit(1)


@main.command()
@click.argument("name")
def uninstall(name):
    """Uninstall a CLI by name."""
    success, msg = uninstall_cli(name)
    if success:
        track_uninstall(name)
        click.secho(f"✓ {msg}", fg="green")
    else:
        click.secho(f"✗ {msg}", fg="red", err=True)
        raise SystemExit(1)


@main.command()
@click.argument("name")
def update(name):
    """Update a CLI to the latest version."""
    click.echo(f"Updating {name}...")
    success, msg = update_cli(name)
    if success:
        cli = get_cli(name)
        track_install(name, cli["version"] if cli else "unknown")
        click.secho(f"✓ {msg}", fg="green")
    else:
        click.secho(f"✗ {msg}", fg="red", err=True)
        raise SystemExit(1)


@main.command("list")
@click.option("--category", "-c", default=None, help="Filter by category.")
@click.option("--source", "-s", default=None, type=click.Choice(["harness", "public", "npm", "all"], case_sensitive=False),
              help="Filter by source (harness, public, or all). 'npm' is kept as an alias for public.")
@click.option("--json", "as_json", is_flag=True, help="Output as JSON.")
def list_clis(category, source, as_json):
    """List all available CLIs."""
    try:
        all_clis = fetch_all_clis()
    except Exception as e:
        click.secho(f"Failed to fetch registry: {e}", fg="red", err=True)
        raise SystemExit(1)

    clis = all_clis
    if category:
        clis = [c for c in clis if c.get("category", "").lower() == category.lower()]
    if source == "npm":
        source = "public"
    if source and source != "all":
        clis = [c for c in clis if c.get("_source", "harness") == source]

    installed = get_installed()

    if as_json:
        import json as json_mod
        click.echo(json_mod.dumps(clis, indent=2))
        return

    if not clis:
        click.echo("No CLIs found." + (f" Category '{category}' may not exist." if category else ""))
        return

    # Group by category
    by_cat = {}
    for cli in clis:
        cat = cli.get("category", "uncategorized")
        by_cat.setdefault(cat, []).append(cli)

    for cat in sorted(by_cat):
        click.secho(f"\n  {cat.upper()}", fg="blue", bold=True)
        for cli in sorted(by_cat[cat], key=lambda c: c["name"]):
            marker = click.style(" ●", fg="green") if cli["name"] in installed else "  "
            name = click.style(f"{cli['name']:20s}", bold=True)
            desc = cli["description"][:55]
            tag = _source_tag(cli)
            click.echo(f"  {marker} {name}{tag} {desc}")

    total = len(clis)
    inst = sum(1 for c in clis if c["name"] in installed)
    harness_count = sum(1 for c in clis if c.get("_source") == "harness")
    public_count = sum(1 for c in clis if c.get("_source") == "public")
    click.echo(f"\n  {total} CLIs available ({harness_count} harness, {public_count} public), {inst} installed")
    cats = list_categories()
    click.echo(f"  Categories: {', '.join(cats)}")


@main.command()
@click.argument("query")
@click.option("--json", "as_json", is_flag=True, help="Output as JSON.")
def search(query, as_json):
    """Search CLIs by name, description, or category."""
    results = search_clis(query)

    if as_json:
        import json as json_mod
        click.echo(json_mod.dumps(results, indent=2))
        return

    if not results:
        click.echo(f"No CLIs matching '{query}'.")
        return

    installed = get_installed()
    for cli in results:
        marker = click.style("●", fg="green") if cli["name"] in installed else " "
        name = click.style(cli["name"], bold=True)
        cat = click.style(f"[{cli.get('category', '')}]", fg="blue")
        tag = _source_tag(cli)
        click.echo(f"  {marker} {name} {cat}{tag} — {cli['description'][:65]}")
        click.echo(f"    Install: cli-hub install {cli['name']}")


@main.command()
@click.argument("name")
def info(name):
    """Show details for a specific CLI."""
    cli = get_cli(name)
    if not cli:
        click.secho(f"CLI '{name}' not found.", fg="red", err=True)
        raise SystemExit(1)

    installed = get_installed()
    is_installed = cli["name"] in installed
    source = cli.get("_source", "harness")

    click.secho(f"\n  {cli['display_name']}", bold=True)
    click.echo(f"  {cli['description']}")
    click.echo(f"  Category:    {cli.get('category', 'N/A')}")
    click.echo(f"  Source:      {source}")
    if source == "public":
        click.echo(f"  Install via: {cli.get('package_manager') or cli.get('install_strategy') or 'public'}")
        if cli.get("npm_package"):
            click.echo(f"  npm package: {cli['npm_package']}")
        if cli.get("npx_cmd"):
            click.echo(f"  npx command: {cli['npx_cmd']}")
        if cli.get("install_cmd"):
            click.echo(f"  Install cmd: {cli['install_cmd']}")
        if cli.get("install_notes"):
            click.echo(f"  Notes:       {cli['install_notes']}")
    click.echo(f"  Version:     {cli['version']}")
    click.echo(f"  Requires:    {cli.get('requires') or 'nothing'}")
    click.echo(f"  Entry point: {cli['entry_point']}")
    if cli.get("skill_md"):
        click.echo(f"  Skill:       {cli['skill_md']}")
    click.echo(f"  Homepage:    {cli.get('homepage', 'N/A')}")
    contributors = cli.get("contributors", [])
    if contributors:
        names = ", ".join(ct["name"] for ct in contributors)
        click.echo(f"  Contributors: {names}")
    status = click.style("installed", fg="green") if is_installed else "not installed"
    click.echo(f"  Status:      {status}")
    click.echo(f"\n  Install: cli-hub install {cli['name']}")
    click.echo()


@main.command()
@click.argument("name")
@click.argument("args", nargs=-1)
def launch(name, args):
    """Launch an installed CLI, passing through any extra arguments."""
    cli = get_cli(name)
    if not cli:
        click.secho(f"CLI '{name}' not found in registry.", fg="red", err=True)
        raise SystemExit(1)

    entry = cli["entry_point"]
    if not shutil.which(entry):
        click.secho(
            f"'{entry}' not found on PATH. Install it first: cli-hub install {name}",
            fg="red",
            err=True,
        )
        raise SystemExit(1)

    track_launch(name)
    os.execvp(entry, [entry] + list(args))


