        return True, f"Updated {cli['display_name']}"
    return False, f"uv update failed:\n{result.stderr or result.stdout}"


# ── npm operations (public CLIs) ──


def _npm_install(cli):
    npm = _find_npm()
    if npm is None:
        return False, (
            "npm is not installed. Install Node.js first:\n"
            "  macOS: brew install node\n"
            "  Linux: curl -fsSL https://deb.nodesource.com/setup_lts.x | sudo -E bash - && sudo apt-get install -y nodejs\n"
            "  Windows: Download from https://nodejs.org"
        )
    result = subprocess.run(
        [npm, "install", "-g", cli["npm_package"]],
        capture_output=True, text=True
    )
    if result.returncode == 0:
        return True, f"Installed {cli['display_name']} ({cli['entry_point']})"
    return False, f"npm install failed:\n{result.stderr}"


def _npm_uninstall(cli):
    npm = _find_npm()
    if npm is None:
        return False, "npm is not installed."
    result = subprocess.run(
        [npm, "uninstall", "-g", cli["npm_package"]],
        capture_output=True, text=True
    )
    if result.returncode == 0:
        return True, f"Uninstalled {cli['display_name']}"
    return False, f"npm uninstall failed:\n{result.stderr}"


def _npm_update(cli):
    npm = _find_npm()
    if npm is None:
        return False, "npm is not installed."
    result = subprocess.run(
        [npm, "install", "-g", cli["npm_package"] + "@latest"],
        capture_output=True, text=True
    )
    if result.returncode == 0:
        return True, f"Updated {cli['display_name']} to latest"
    return False, f"Update failed:\n{result.stderr}"


def _perform_action(cli, action):
    """Dispatch install/uninstall/update based on CLI strategy."""
    strategy = _install_strategy(cli)
    actions = {
        "pip": {"install": _pip_install, "uninstall": _pip_uninstall, "update": _pip_update},
        "npm": {"install": _npm_install, "uninstall": _npm_uninstall, "update": _npm_update},
        "uv": {"install": _uv_install, "uninstall": _uv_uninstall, "update": _uv_update},
        "command": {"install": _generic_install, "uninstall": _generic_uninstall, "update": _generic_update},
        "bundled": {"install": _bundled_install, "uninstall": _bundled_uninstall, "update": _bundled_update},
    }
    handler = actions.get(strategy, actions["command"]).get(action)
    return strategy, handler(cli)


def _installed_entry(cli, source, strategy):
    """Return the installed.json payload for a CLI."""
    entry = {
        "version": cli["version"],
        "entry_point": cli["entry_point"],
        "source": source,
        "strategy": strategy,
    }
    if cli.get("package_manager"):
        entry["package_manager"] = cli["package_manager"]
    if cli.get("npm_package"):
        entry["npm_package"] = cli["npm_package"]
    if cli.get("install_cmd"):
        entry["install_cmd"] = cli["install_cmd"]
    if cli.get("uninstall_cmd"):
        entry["uninstall_cmd"] = cli["uninstall_cmd"]
    if cli.get("update_cmd"):
        entry["update_cmd"] = cli["update_cmd"]
    return entry


# ── Unified interface ──


def install_cli(name):
    """Install a CLI by name. Dispatches to pip or npm based on source. Returns (success, message)."""
    cli = get_cli(name)
    if cli is None:
        return False, f"CLI '{name}' not found in registry. Use 'cli-hub list' to see available CLIs."

    source = cli.get("_source", "harness")
    strategy, (success, msg) = _perform_action(cli, "install")

    if success:
        installed = _load_installed()
        installed[cli["name"]] = _installed_entry(cli, source, strategy)
        _save_installed(installed)

    return success, msg


def uninstall_cli(name):
    """Uninstall a CLI by name. Returns (success, message)."""
    cli = get_cli(name)
    if cli is None:
        return False, f"CLI '{name}' not found in registry."

    _, (success, msg) = _perform_action(cli, "uninstall")

    if success:
        installed = _load_installed()
        installed.pop(cli["name"], None)
        _save_installed(installed)

    return success, msg


def update_cli(name):
    """Update a CLI by reinstalling. Returns (success, message)."""
    cli = get_cli(name, force_refresh=True)
    if cli is None:
        return False, f"CLI '{name}' not found in registry."

    source = cli.get("_source", "harness")
    strategy, (success, msg) = _perform_action(cli, "update")

    if success:
        installed = _load_installed()
        installed[cli["name"]] = _installed_entry(cli, source, strategy)
        _save_installed(installed)

    return success, msg


def get_installed():
    """Return dict of installed CLIs."""
    return _load_installed()


def _scope_label(scope, capabilities=None):
    """Human-readable label for an install scope (used in state + output)."""
    scope_type = scope.get("type")
    if scope_type == "capability":
        return f"capability {scope.get('value')}"
    if scope_type == "recipe":
        return f"recipe {scope.get('value')}"
    if scope_type == "only":
        return f"only {', '.join(scope.get('value', []))}"
    return "full matrix"


def plan_matrix_install(name, capability=None, recipe=None, only=None):
    """Compute what ``matrix install`` would do — no side effects (F2.1).

    Returns ``(ok, payload)``. ``ok`` is false only on lookup/usage errors;
    ``payload['arg_error']`` distinguishes usage errors (exit 2) from not-found.
    """
    matrix_item = get_matrix(name)
    if matrix_item is None:
        return False, {"error": f"Matrix '{name}' not found. Use 'cli-hub matrix list' to see available matrices."}

    scope = resolve_install_scope(matrix_item, capability=capability, recipe=recipe, only=only)
    if scope.get("error"):
        return False, {"error": scope["error"], "arg_error": True, "matrix": matrix_item}

    installed = set(get_installed())
    plan = []
    for cli_name in scope["cli_names"]:
        cli = get_cli(cli_name)
        if cli_name in installed:
            action, via = "skip", (_install_strategy(cli) if cli else None)
        elif cli is None:
            action, via = "error", None
        else:
            action, via = "install", _install_strategy(cli)
        plan.append({
            "name": cli_name,
            "display_name": cli["display_name"] if cli else cli_name,
            "action": action,
            "via": via,
            "already_installed": cli_name in installed,
            "found": cli is not None,
        })

    scope_caps = scope.get("capabilities")
    cap_objs = None
    if scope_caps is not None and scope["scope"].get("type") in {"capability", "recipe"}:
        cap_set = set(scope_caps)
        cap_objs = [c for c in matrix_item.get("capabilities", []) if c.get("id") in cap_set]
    not_managed = unmanaged_providers(matrix_item, cap_objs)

    summary = {
        "total": len(plan),
        "to_install": sum(1 for p in plan if p["action"] == "install"),
        "to_skip": sum(1 for p in plan if p["action"] == "skip"),
        "unresolved": sum(1 for p in plan if p["action"] == "error"),
    }
    payload = {
        "matrix": matrix_item,
        "scope": scope["scope"],
        "scope_label": _scope_label(scope["scope"]),
        "plan": plan,
        "not_managed": not_managed,
        "summary": summary,
    }
    return True, payload


def install_matrix(name, capability=None, recipe=None, only=None, resume=False):
    """Install the CLIs in a named matrix, optionally scoped (F2.2) or resumed (F2.3).

    Returns ``(success, payload)``. ``payload['arg_error']`` marks usage errors.
    Records per-CLI outcomes to ``matrix_state.json`` so ``--resume`` and
    ``matrix doctor`` can act on them.
    """
    matrix_item = get_matrix(name)
    if matrix_item is None:
        return False, {"error": f"Matrix '{name}' not found. Use 'cli-hub matrix list' to see available matrices."}

    state = _load_matrix_state()

    if resume:
        if capability or recipe or only:
            return False, {"error": "Cannot combine --resume with --capability/--recipe/--only.",
                           "arg_error": True, "matrix": matrix_item}
        prior = state.get(name)
        if not prior:
            return False, {"error": f"No previous install of '{name}' to resume. "
                                    f"Run 'cli-hub matrix install {name}' first.",
                           "arg_error": True, "matrix": matrix_item}
        target_names = [r["name"] for r in prior.get("results", []) if r.get("status") == "failed"]
        scope = prior.get("scope", {"type": "all"})
        if not target_names:
            return True, {"matrix": matrix_item, "results": [], "scope": scope,
                          "scope_label": _scope_label(scope),
                          "summary": {"total": 0, "installed": 0, "skipped": 0, "failed": 0},
                          "resumed": True, "nothing_to_resume": True}
    else:
        scope_info = resolve_install_scope(matrix_item, capability=capability, recipe=recipe, only=only)
        if scope_info.get("error"):
            return False, {"error": scope_info["error"], "arg_error": True, "matrix": matrix_item}
        target_names = scope_info["cli_names"]
        scope = scope_info["scope"]

    installed = set(get_installed())
    results = []

    for cli_name in target_names:
        cli = get_cli(cli_name)
        display_name = cli["display_name"] if cli else cli_name
        via = _install_strategy(cli) if cli else None

        if cli_name in installed:
            results.append({"name": cli_name, "display_name": display_name,
                            "status": "skipped", "via": via, "message": "Already installed"})
            continue

        if cli is None:
            results.append({"name": cli_name, "display_name": display_name,
                            "status": "failed", "via": via, "message": "CLI not found in registry"})
            continue

        success, msg = install_cli(cli_name)
        results.append({"name": cli_name, "display_name": display_name,
                        "status": "installed" if success else "failed", "via": via, "message": msg})
        if success:
            installed.add(cli_name)

    summary = {
        "total": len(results),
        "installed": sum(1 for result in results if result["status"] == "installed"),
        "skipped": sum(1 for result in results if result["status"] == "skipped"),
        "failed": sum(1 for result in results if result["status"] == "failed"),
    }

    state[name] = {
        "last_run": datetime.now().isoformat(timespec="seconds"),
        "scope": scope,
        "results": results,
    }
    _save_matrix_state(state)

    installed_state = get_installed()
    rendered_skill_path = render_matrix_skill_file(matrix_item, installed=installed_state)
    payload = {
        "matrix": matrix_item,
        "results": results,
        "scope": scope,
        "scope_label": _scope_label(scope),
        "summary": summary,
        "resumed": resume,
        "rendered_skill_path": str(rendered_skill_path),
    }
    return summary["failed"] == 0, payload


def doctor_matrix(name):
    """Audit install completeness for a matrix's CLIs against the environment (F2.3).

    Unlike preflight (which reports provider availability for selection), doctor
    checks whether the matrix's own ``clis[]`` are installed and on PATH, and
    emits a fix command per broken/missing member.
    """
    matrix_item = get_matrix(name)
    if matrix_item is None:
        return False, {"error": f"Matrix '{name}' not found. Use 'cli-hub matrix list' to see available matrices."}

    installed = get_installed()
    state = _load_matrix_state().get(name)
    checks = []
    for cli_name in matrix_item.get("clis", []):
        cli = get_cli(cli_name)
        entry_point = cli.get("entry_point") if cli else None
        record = installed.get(cli_name)

        if record is None:
            status = "not_installed"
            detail = "Not installed"
            fix = f"cli-hub install {cli_name}"
        elif entry_point and not _command_exists(entry_point):
            status = "broken"
            detail = f"Recorded as installed but '{entry_point}' is not on PATH"
            fix = f"cli-hub install {cli_name}"
        else:
            status = "ok"
            detail = "Installed"
            fix = None

        checks.append({
            "name": cli_name,
            "entry_point": entry_point,
            "status": status,
            "detail": detail,
            "fix": fix,
        })

    summary = {
        "total": len(checks),
        "ok": sum(1 for check in checks if check["status"] == "ok"),
        "broken": sum(1 for check in checks if check["status"] == "broken"),
        "not_installed": sum(1 for check in checks if check["status"] == "not_installed"),
    }
    payload = {
        "matrix": matrix_item,
        "last_run": state.get("last_run") if state else None,
        "checks": checks,
        "summary": summary,
    }
    healthy = summary["broken"] == 0 and summary["not_installed"] == 0
    return healthy, payload

"""Fetch, cache, and query curated CLI workflow matrices."""

import importlib.metadata
import importlib.util
import json
import os
import shutil
import time
from pathlib import Path

import requests

MATRIX_REGISTRY_URL = "https://hkuds.github.io/CLI-Anything/matrix_registry.json"
MATRIX_CACHE_FILE = Path.home() / ".cli-hub" / "matrix_registry_cache.json"
CACHE_TTL = 3600  # 1 hour

AGENT_INSTALLABLE_KINDS = {"agent-skill"}

# Provider kinds whose CLIs `matrix install` can manage via cli-hub / public registries.
INSTALLABLE_KINDS = {"harness-cli", "public-cli"}

# Harness CLI providers are named `cli-anything-<cli>`; the flat `clis[]` list uses `<cli>`.
HARNESS_PREFIX = "cli-anything-"

# Short, stable labels for provider kinds used across search / can / preflight output.
KIND_LABELS = {
    "harness-cli": "harness",
    "public-cli": "public",
    "python": "python",
    "native": "native",
    "api": "api",
    "agent-skill": "skill",
    "agent-native": "native",
    "web-search": "web",
}


def _ensure_cache_dir():
    MATRIX_CACHE_FILE.parent.mkdir(parents=True, exist_ok=True)


def _load_cached_data():
    if not MATRIX_CACHE_FILE.exists():
        return None
    try:
        cached = json.loads(MATRIX_CACHE_FILE.read_text())
        return cached["data"]
    except (json.JSONDecodeError, KeyError):
        return None


def _load_local_registry():
    """Load matrix_registry.json from a source checkout when available."""
    for parent in Path(__file__).resolve().parents:
        candidate = parent / "matrix_registry.json"
        if not candidate.exists():
            continue
        try:
            return json.loads(candidate.read_text())
        except json.JSONDecodeError:
            return None
    return None


def fetch_matrix_registry(force_refresh=False):
    """Fetch the matrix registry with local file caching."""
    _ensure_cache_dir()

    if not force_refresh and MATRIX_CACHE_FILE.exists():
        try:
            cached = json.loads(MATRIX_CACHE_FILE.read_text())
            if time.time() - cached.get("_cached_at", 0) < CACHE_TTL:
                return cached["data"]
        except (json.JSONDecodeError, KeyError):
            pass

    try:
        resp = requests.get(MATRIX_REGISTRY_URL, timeout=15)
        resp.raise_for_status()
        data = resp.json()
    except (requests.RequestException, ValueError):
        cached_data = _load_cached_data()
        if cached_data is not None:
            return cached_data
        local_data = _load_local_registry()
        if local_data is not None:
            return local_data
        raise

    MATRIX_CACHE_FILE.write_text(json.dumps({"_cached_at": time.time(), "data": data}, indent=2))
    return data


def fetch_all_matrices(force_refresh=False):
    """Return all matrix entries."""
    return fetch_matrix_registry(force_refresh).get("matrices", [])


def get_matrix(name, force_refresh=False):
    """Look up a matrix entry by name (case-insensitive)."""
    name_lower = name.lower()
    for matrix_item in fetch_all_matrices(force_refresh):
        if matrix_item["name"].lower() == name_lower:
            return matrix_item
    return None


def _string_values(value):
    """Yield lowercase strings from nested matrix registry values."""
    if isinstance(value, str):
        yield value.lower()
    elif isinstance(value, dict):
        for child in value.values():
            yield from _string_values(child)
    elif isinstance(value, list):
        for child in value:
            yield from _string_values(child)


def search_matrices(query, force_refresh=False):
    """Search matrices by name, capabilities, providers, recipes, or gaps."""
    query_lower = query.lower()
    results = []
    for matrix_item in fetch_all_matrices(force_refresh):
        haystack_values = {
            "name": matrix_item.get("name", ""),
            "display_name": matrix_item.get("display_name", ""),
            "description": matrix_item.get("description", ""),
            "category": matrix_item.get("category", ""),
            "matrix_id": matrix_item.get("matrix_id", ""),
            "capabilities": matrix_item.get("capabilities", []),
            "recipes": matrix_item.get("recipes", []),
            "known_gaps": matrix_item.get("known_gaps", []),
            "clis": matrix_item.get("clis", []),
        }
        if any(query_lower in value for value in _string_values(haystack_values)):
            results.append(matrix_item)
    return results


def _as_list(value):
    """Normalize registry requirement fields to lists."""
    if value is None:
        return []
    if isinstance(value, list):
        return value
    return [value]


def _package_available(name):
    try:
        if importlib.util.find_spec(name) is not None:
            return True
    except Exception:
        pass
    try:
        normalized = name.replace("-", "_")
        if normalized != name and importlib.util.find_spec(normalized) is not None:
            return True
    except Exception:
        pass
    try:
        importlib.metadata.version(name)
        return True
    except Exception:
        pass
    return False


def check_provider_requirements(provider):
    """Check whether a provider's declared requirements are available locally."""
    kind = provider.get("kind", "")
    if kind in AGENT_INSTALLABLE_KINDS:
        return {
            "name": provider.get("name", ""),
            "kind": kind,
            "available": False,
            "agent_installable": True,
            "status": "agent-installable",
            "offline": bool(provider.get("offline")),
            "cost_tier": provider.get("cost_tier", "unknown"),
            "quality_tier": provider.get("quality_tier", "unknown"),
            "requires": provider.get("requires") or {},
            "present": {"env": [], "binary": [], "package": []},
            "missing": {"env": [], "binary": [], "package": []},
            "notes": provider.get("notes", ""),
            "install_hint": provider.get("install_hint"),
        }

    requires = provider.get("requires") or {}
    env_names = _as_list(requires.get("env"))
    binary_names = _as_list(requires.get("binary"))
    package_names = _as_list(requires.get("package"))

    present = {
        "env": [name for name in env_names if os.environ.get(name)],
        "binary": [name for name in binary_names if shutil.which(name)],
        "package": [name for name in package_names if _package_available(name)],
    }
    missing = {
        "env": [name for name in env_names if name not in present["env"]],
        "binary": [name for name in binary_names if name not in present["binary"]],
        "package": [name for name in package_names if name not in present["package"]],
    }
    available = not any(missing.values())

    return {
        "name": provider.get("name", ""),
        "kind": kind,
        "available": available,
        "agent_installable": False,
        "status": "available" if available else "missing",
        "offline": bool(provider.get("offline")),
        "cost_tier": provider.get("cost_tier", "unknown"),
        "quality_tier": provider.get("quality_tier", "unknown"),
        "requires": requires,
        "present": present,
        "missing": missing,
        "notes": provider.get("notes", ""),
        "install_hint": provider.get("install_hint"),
    }


def preflight_matrix(matrix_item, capability_id=None, offline=False, capability_ids=None):
    """Return provider availability for a matrix, optionally filtered.

    ``capability_id`` filters to a single capability; ``capability_ids`` (a set or
    list, used by ``--recipe``) filters to a named subset. The two compose.
    """
    id_filter = set(capability_ids) if capability_ids is not None else None
    capability_results = []

    for capability in matrix_item.get("capabilities", []):
        if capability_id and capability.get("id") != capability_id:
            continue
        if id_filter is not None and capability.get("id") not in id_filter:
            continue

        provider_results = [
            check_provider_requirements(provider)
            for provider in capability.get("providers", [])
            if not offline or provider.get("offline")
        ]
        capability_results.append({
            "id": capability.get("id", ""),
            "intent": capability.get("intent", ""),
            "provider_count": len(provider_results),
            "available_count": sum(1 for provider in provider_results if provider["available"]),
            "agent_installable_count": sum(
                1 for provider in provider_results
                if provider.get("agent_installable")
            ),
            "providers": provider_results,
        })

    summary = {
        "capabilities": len(capability_results),
        "with_available_provider": sum(1 for cap in capability_results if cap["available_count"] > 0),
        "with_agent_installable_provider": sum(
            1 for cap in capability_results
            if cap["available_count"] == 0 and cap["agent_installable_count"] > 0
        ),
        "providers": sum(cap["provider_count"] for cap in capability_results),
        "available_providers": sum(cap["available_count"] for cap in capability_results),
        "agent_installable_providers": sum(
            cap["agent_installable_count"] for cap in capability_results
        ),
    }
    # A capability is "covered" when it has at least one available provider or an
    # agent-installable fallback; everything else is a hard gap (drives exit code 3).
    summary["covered"] = sum(
        1 for cap in capability_results
        if cap["available_count"] > 0 or cap["agent_installable_count"] > 0
    )
    summary["gaps"] = summary["capabilities"] - summary["covered"]

    return {
        "matrix": {
            "name": matrix_item.get("name", ""),
            "display_name": matrix_item.get("display_name", matrix_item.get("name", "")),
            "schema_version": matrix_item.get("schema_version", "1"),
        },
        "capability_filter": capability_id,
        "offline": offline,
        "summary": summary,
        "capabilities": capability_results,
    }


# ── Provider ↔ CLI resolution and install scoping (F2.2) ──────────────────────


def provider_cli_name(provider, cli_names):
    """Resolve a provider to the ``clis[]`` member that ``matrix install`` manages.

    Returns the registry CLI name, or ``None`` when the provider is not installable
    through cli-hub (Python libs, native binaries, cloud APIs, agent skills, or
    third-party public CLIs that live outside the matrix's ``clis[]`` list).
    """
    if provider.get("kind") not in INSTALLABLE_KINDS:
        return None
    cli_set = set(cli_names)
    explicit = provider.get("cli")  # forward-compatible with schema v2.1 (F4.2)
    if explicit and explicit in cli_set:
        return explicit
    name = provider.get("name", "")
    if name in cli_set:
        return name
    if name.startswith(HARNESS_PREFIX):
        stripped = name[len(HARNESS_PREFIX):]
        if stripped in cli_set:
            return stripped
    return None


def provider_install_hint(provider, cli_names):
    """Return a human-readable install command for a provider, or ``None``.

    Prefers the registry's explicit ``install_hint`` (F2.4); otherwise derives
    ``cli-hub install <cli>`` for providers that map into the matrix's ``clis[]``.
    """
    hint = provider.get("install_hint")
    if hint:
        return hint
    cli = provider_cli_name(provider, cli_names)
    if cli:
        return f"cli-hub install {cli}"
    return None


def get_recipe(matrix_item, recipe_id):
    """Look up a recipe entry by id (case-insensitive)."""
    recipe_lower = recipe_id.lower()
    for recipe in matrix_item.get("recipes", []):
        if recipe.get("id", "").lower() == recipe_lower:
            return recipe
    return None


def _scope_clis_for_capabilities(matrix_item, capabilities):
    """Return the ``clis[]`` members backing the given capabilities, in registry order."""
    cli_names = matrix_item.get("clis", [])
    wanted = set()
    for capability in capabilities:
        for provider in capability.get("providers", []):
            cli = provider_cli_name(provider, cli_names)
            if cli:
                wanted.add(cli)
    return [name for name in cli_names if name in wanted]


def resolve_install_scope(matrix_item, capability=None, recipe=None, only=None):
    """Resolve install scope flags to a concrete subset of the matrix's ``clis[]``.

    Returns a dict with ``cli_names`` (ordered subset), ``scope`` (type/value),
    ``capabilities`` (capability ids in scope, when applicable), and ``error``
    (a usage message when the selectors are invalid or mutually exclusive).
    """
    cli_names = matrix_item.get("clis", [])
    selectors = [(kind, value) for kind, value in
                 (("capability", capability), ("recipe", recipe), ("only", only)) if value]

    if len(selectors) > 1:
        return {"error": "Use only one of --capability, --recipe, or --only.",
                "scope": {"type": "invalid"}, "cli_names": [], "capabilities": []}

    if not selectors:
        return {"error": None, "scope": {"type": "all"}, "cli_names": list(cli_names),
                "capabilities": [c.get("id") for c in matrix_item.get("capabilities", [])]}

    sel_type, sel_value = selectors[0]

    if sel_type == "only":
        requested = [name.strip() for name in only.split(",") if name.strip()]
        unknown = [name for name in requested if name not in set(cli_names)]
        if unknown:
            return {"error": (f"Not in matrix '{matrix_item.get('name')}' clis[]: "
                              f"{', '.join(unknown)}. Valid: {', '.join(cli_names) or '(none)'}"),
                    "scope": {"type": "only"}, "cli_names": [], "capabilities": []}
        chosen = [name for name in cli_names if name in set(requested)]
        return {"error": None, "scope": {"type": "only", "value": requested},
                "cli_names": chosen, "capabilities": []}

    if sel_type == "capability":
        capability_item = next(
            (c for c in matrix_item.get("capabilities", []) if c.get("id") == capability), None)
        if capability_item is None:
            valid = ", ".join(c.get("id", "") for c in matrix_item.get("capabilities", []))
            return {"error": (f"Capability '{capability}' not found in "
                              f"'{matrix_item.get('name')}'. Valid: {valid or '(none)'}"),
                    "scope": {"type": "capability"}, "cli_names": [], "capabilities": []}
        return {"error": None, "scope": {"type": "capability", "value": capability},
                "cli_names": _scope_clis_for_capabilities(matrix_item, [capability_item]),
                "capabilities": [capability]}

    # sel_type == "recipe"
    recipe_item = get_recipe(matrix_item, recipe)
    if recipe_item is None:
        valid = ", ".join(r.get("id", "") for r in matrix_item.get("recipes", []))
        return {"error": (f"Recipe '{recipe}' not found in '{matrix_item.get('name')}'. "
                          f"Valid: {valid or '(none)'}"),
                "scope": {"type": "recipe"}, "cli_names": [], "capabilities": []}
    used = recipe_item.get("capabilities_used", [])
    used_set = set(used)
    capabilities = [c for c in matrix_item.get("capabilities", []) if c.get("id") in used_set]
    return {"error": None, "scope": {"type": "recipe", "value": recipe},
            "cli_names": _scope_clis_for_capabilities(matrix_item, capabilities),
            "capabilities": list(used)}


def unmanaged_providers(matrix_item, capabilities=None):
    """Group providers that ``matrix install`` does NOT install, by category.

    Used by ``install --dry-run`` to show what still needs manual setup
    (Python libs, native binaries, cloud APIs, agent skills, and third-party
    public CLIs outside ``clis[]``).
    """
    cli_names = matrix_item.get("clis", [])
    caps = capabilities if capabilities is not None else matrix_item.get("capabilities", [])
    buckets = {"python": [], "native": [], "api": [], "agent-skill": [], "public-unmanaged": []}
    seen = set()
    for capability in caps:
        for provider in capability.get("providers", []):
            kind = provider.get("kind")
            name = provider.get("name", "")
            key = (kind, name)
            if key in seen:
                continue
            if kind in INSTALLABLE_KINDS:
                if kind == "public-cli" and provider_cli_name(provider, cli_names) is None:
                    buckets["public-unmanaged"].append(name)
                    seen.add(key)
                continue
            if kind in buckets:
                buckets[kind].append(name)
                seen.add(key)
    return {category: names for category, names in buckets.items() if names}


# ── Capability-level search (F1.1 / F1.4) ─────────────────────────────────────


def providers_summary(capability, limit=4):
    """Render a compact 'name (kind) · …' summary of a capability's providers."""
    providers = capability.get("providers", [])
    parts = [
        f"{p.get('name', '')} ({KIND_LABELS.get(p.get('kind'), p.get('kind', '?'))})"
        for p in providers[:limit]
    ]
    summary = " · ".join(parts)
    extra = len(providers) - limit
    if extra > 0:
        summary += f" · +{extra} more"
    return summary


def _capability_match_field(capability, query_lower):
    """Return which field of a capability matched the query, or ``None``."""
    if query_lower in capability.get("id", "").lower():
        return "id"
    if query_lower in capability.get("intent", "").lower():
        return "intent"
    if any(query_lower in hint.lower() for hint in capability.get("skill_search_hints", [])):
        return "hint"
    for provider in capability.get("providers", []):
        if query_lower in provider.get("name", "").lower():
            return "provider"
    return None


def capability_matches(matrix_item, query_lower):
    """Return per-capability match attribution for a single matrix (F1.1 matched_in)."""
    matches = []
    for capability in matrix_item.get("capabilities", []):
        field = _capability_match_field(capability, query_lower)
        if not field:
            continue
        matches.append({
            "matrix": matrix_item.get("name", ""),
            "matrix_id": matrix_item.get("matrix_id", ""),
            "capability_id": capability.get("id", ""),
            "intent": capability.get("intent", ""),
            "match_field": field,
            "providers_summary": providers_summary(capability),
        })
    return matches


def search_capabilities(query, force_refresh=False):
    """Search every matrix at capability granularity (powers ``cli-hub can``).

    Each hit carries local provider availability so callers can show what is
    usable on this machine right now.
    """
    query_lower = query.lower()
    hits = []
    for matrix_item in fetch_all_matrices(force_refresh):
        for capability in matrix_item.get("capabilities", []):
            field = _capability_match_field(capability, query_lower)
            if not field:
                continue
            hits.append({
                "matrix": matrix_item.get("name", ""),
                "matrix_id": matrix_item.get("matrix_id", ""),
                "capability_id": capability.get("id", ""),
                "intent": capability.get("intent", ""),
                "match_field": field,
                "providers": [
                    check_provider_requirements(provider)
                    for provider in capability.get("providers", [])
                ],
            })
    return hits


def all_recipes(query=None, force_refresh=False):
    """Return recipes across all matrices, optionally filtered by a query (F1.4)."""
    query_lower = query.lower() if query else None
    out = []
    for matrix_item in fetch_all_matrices(force_refresh):
        for recipe in matrix_item.get("recipes", []):
            if query_lower:
                haystack = " ".join([
                    recipe.get("id", ""),
                    recipe.get("description", ""),
                    " ".join(recipe.get("capabilities_used", [])),
                ]).lower()
                if query_lower not in haystack:
                    continue
            out.append({
                "matrix": matrix_item.get("name", ""),
                "matrix_id": matrix_item.get("matrix_id", ""),
                "id": recipe.get("id", ""),
                "description": recipe.get("description", ""),
                "capabilities_used": recipe.get("capabilities_used", []),
            })
    return out

"""Preview bundle inspection, live session rendering, and popup helpers."""

from __future__ import annotations

import functools
import html
import json
import os
import shutil
import subprocess
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple


def _read_json(path: Path) -> Dict[str, Any]:
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def resolve_bundle_ref(bundle_ref: str) -> Tuple[Path, Path]:
    ref = Path(bundle_ref).expanduser().resolve()
    if ref.is_dir():
        manifest = ref / "manifest.json"
        if not manifest.is_file():
            raise FileNotFoundError(f"manifest.json not found in bundle directory: {ref}")
        return ref, manifest
    if ref.is_file():
        if ref.name != "manifest.json":
            raise ValueError("Bundle ref must be a bundle directory or a manifest.json path")
        return ref.parent, ref
    raise FileNotFoundError(f"Bundle ref not found: {bundle_ref}")


def resolve_session_ref(session_ref: str) -> Tuple[Path, Path]:
    ref = Path(session_ref).expanduser().resolve()
    if ref.is_dir():
        session_path = ref / "session.json"
        if not session_path.is_file():
            raise FileNotFoundError(f"session.json not found in live session directory: {ref}")
        return ref, session_path
    if ref.is_file():
        if ref.name != "session.json":
            raise ValueError("Session ref must be a live session directory or a session.json path")
        return ref.parent, ref
    raise FileNotFoundError(f"Session ref not found: {session_ref}")


def is_live_session_ref(preview_ref: str) -> bool:
    ref = Path(preview_ref).expanduser().resolve()
    if ref.is_dir():
        return (ref / "session.json").is_file()
    return ref.is_file() and ref.name == "session.json"


def load_bundle(bundle_ref: str) -> Tuple[Path, Dict[str, Any], Dict[str, Any]]:
    bundle_dir, manifest_path = resolve_bundle_ref(bundle_ref)
    manifest = _read_json(manifest_path)
    summary_rel = manifest.get("summary_path", "summary.json")
    summary_path = (bundle_dir / summary_rel).resolve()
    summary = _read_json(summary_path) if summary_path.is_file() else {}
    return bundle_dir, manifest, summary


def load_session(session_ref: str) -> Tuple[Path, Dict[str, Any]]:
    session_dir, session_path = resolve_session_ref(session_ref)
    return session_dir, _read_json(session_path)


def format_bytes(size: int) -> str:
    if size < 1024:
        return f"{size} B"
    if size < 1024 * 1024:
        return f"{size / 1024:.1f} KB"
    if size < 1024 * 1024 * 1024:
        return f"{size / (1024 * 1024):.1f} MB"
    return f"{size / (1024 * 1024 * 1024):.1f} GB"


_TRAJECTORY_FILENAMES = ("trajectory.json", "timeline.json")
_TRAJECTORY_CONTAINER_KEYS = {"trajectory", "timeline"}
_TRAJECTORY_PATH_KEYS = {
    "trajectory_path",
    "timeline_path",
    "trajectory_file",
    "timeline_file",
    "trajectory_ref",
    "timeline_ref",
}


def _coalesce(*values: Any) -> Any:
    for value in values:
        if value is None:
            continue
        if isinstance(value, str) and not value.strip():
            continue
        return value
    return None


def _stringify_command(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, str):
        value = value.strip()
        return value or None
    if isinstance(value, (list, tuple)):
        text = " ".join(str(part) for part in value if part is not None)
        return text.strip() or None
    if isinstance(value, dict):
        for key in ("display", "display_cmd", "command", "raw", "argv"):
            if key in value:
                return _stringify_command(value[key])
        return json.dumps(value, ensure_ascii=False, sort_keys=True)
    return str(value)


def _normalize_index(value: Any, fallback: int) -> int:
    if isinstance(value, bool):
        return fallback
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    if isinstance(value, str):
        stripped = value.strip()
        if stripped.isdigit():
            return int(stripped)
    return fallback


def _resolve_ref_path(base_dir: Path, path_ref: str) -> Path:
    ref = Path(path_ref).expanduser()
    if not ref.is_absolute():
        ref = (base_dir / ref).resolve()
    else:
        ref = ref.resolve()
    return ref


def _iter_trajectory_hints(node: Any, *, _seen: Optional[set[int]] = None) -> Iterable[Tuple[str, Any, str]]:
    if _seen is None:
        _seen = set()
    if not isinstance(node, (dict, list)):
        return
    node_id = id(node)
    if node_id in _seen:
        return
    _seen.add(node_id)
    if isinstance(node, list):
        for item in node:
            yield from _iter_trajectory_hints(item, _seen=_seen)
        return
    for key, value in node.items():
        lower = str(key).lower()
        if lower in _TRAJECTORY_CONTAINER_KEYS:
            if isinstance(value, dict):
                yield ("object", value, lower)
            elif isinstance(value, str):
                yield ("path", value, lower)
        elif lower in _TRAJECTORY_PATH_KEYS and isinstance(value, str):
            yield ("path", value, lower)
        if isinstance(value, (dict, list)):
            yield from _iter_trajectory_hints(value, _seen=_seen)


def _trajectory_candidate_refs(base_dir: Path, *payloads: Dict[str, Any]) -> List[str]:
    refs: List[str] = []
    seen = set()
    for payload in payloads:
        if not isinstance(payload, dict):
            continue
        for kind, value, _label in _iter_trajectory_hints(payload):
            if kind != "path" or not isinstance(value, str):
                continue
            resolved = _resolve_ref_path(base_dir, value)
            if not resolved.is_file():
                continue
            rel = os.path.relpath(resolved, base_dir)
            if rel not in seen:
                refs.append(rel)
                seen.add(rel)
    for filename in _TRAJECTORY_FILENAMES:
        if filename not in seen:
            refs.append(filename)
            seen.add(filename)
    return refs


def _extract_bundle_payload(item: Dict[str, Any]) -> Dict[str, Any]:
    for key in ("copied_bundle", "bundle", "preview_bundle", "current_bundle", "published_bundle"):
        value = item.get(key)
        if isinstance(value, dict):
            return value
    return item


def _normalize_timeline_row(item: Any, index: int) -> Dict[str, Any]:
    if not isinstance(item, dict):
        return {
            "order_index": index,
            "step_index": index,
            "step_id": f"step-{index:03d}",
            "step_label": str(item),
            "command": None,
            "command_started_at": None,
            "command_finished_at": None,
            "timeline_ready_at": None,
            "publish_reason": None,
            "bundle_id": None,
            "bundle_dir": None,
            "manifest_path": None,
            "summary_path": None,
            "status": None,
            "stage_label": None,
            "note": None,
        }

    bundle = _extract_bundle_payload(item)
    command = _stringify_command(
        _coalesce(
            item.get("command"),
            item.get("display_cmd"),
            item.get("display_command"),
            item.get("argv"),
            item.get("raw_command"),
        )
    )
    step_index = _normalize_index(
        _coalesce(item.get("step_index"), item.get("index"), item.get("sequence_index")),
        index,
    )
    status = item.get("status")
    if status is None and "returncode" in item:
        status = "ok" if int(item.get("returncode", 1)) == 0 else "error"

    return {
        "order_index": index,
        "step_index": step_index,
        "step_id": str(
            _coalesce(item.get("step_id"), item.get("id"), item.get("command_id"), f"step-{step_index:03d}")
        ),
        "step_label": _coalesce(
            item.get("step_label"),
            item.get("label"),
            item.get("title"),
            item.get("name"),
            item.get("stage_title"),
            item.get("stage_label"),
        ),
        "command": command,
        "command_started_at": _coalesce(
            item.get("command_started_at"),
            item.get("started_at"),
            item.get("timeline_start_s"),
            item.get("start_s"),
        ),
        "command_finished_at": _coalesce(
            item.get("command_finished_at"),
            item.get("finished_at"),
            item.get("timeline_end_s"),
            item.get("end_s"),
            item.get("completed_at"),
        ),
        "timeline_ready_at": _coalesce(
            item.get("timeline_ready_s"),
            item.get("ready_at"),
            item.get("published_at"),
            item.get("created_at"),
        ),
        "publish_reason": _coalesce(item.get("publish_reason"), item.get("reason")),
        "bundle_id": _coalesce(item.get("bundle_id"), bundle.get("bundle_id")),
        "bundle_dir": _coalesce(item.get("bundle_dir"), bundle.get("bundle_dir")),
        "manifest_path": _coalesce(item.get("manifest_path"), bundle.get("manifest_path")),
        "summary_path": _coalesce(item.get("summary_path"), bundle.get("summary_path")),
        "status": status,
        "stage_label": _coalesce(
            item.get("stage_title"),
            item.get("stage_label"),
            item.get("stage_id"),
            item.get("stage"),
        ),
        "note": _coalesce(
            item.get("note"),
            item.get("stage_story"),
            item.get("story"),
            item.get("description"),
        ),
    }


def _merge_timeline_rows(target: Dict[str, Any], source: Dict[str, Any]) -> None:
    for key in (
        "step_label",
        "command",
        "command_started_at",
        "command_finished_at",
        "timeline_ready_at",
        "publish_reason",
        "bundle_id",
        "bundle_dir",
        "manifest_path",
        "summary_path",
        "status",
        "stage_label",
        "note",
    ):
        target[key] = _coalesce(target.get(key), source.get(key))


def _pick_trajectory_events(raw: Dict[str, Any]) -> List[Dict[str, Any]]:
    for key in ("preview_events", "events", "publishes", "entries", "history", "steps", "timeline"):
        value = raw.get(key)
        if isinstance(value, list) and value:
            return value
    return []


def _sort_timeline_rows(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    def sort_key(row: Dict[str, Any]) -> Tuple[int, int, str]:
        step_index = _normalize_index(row.get("step_index"), row.get("order_index", 0))
        order_index = _normalize_index(row.get("order_index"), step_index)
        finish = _coalesce(row.get("command_finished_at"), row.get("timeline_ready_at"), "")
        return step_index, order_index, str(finish)

    return sorted(rows, key=sort_key)


def _normalize_trajectory(raw: Optional[Dict[str, Any]], *, fallback_history: Optional[List[Dict[str, Any]]] = None) -> Optional[Dict[str, Any]]:
    if not raw and not fallback_history:
        return None

    rows: List[Dict[str, Any]] = []
    rows_by_id: Dict[str, Dict[str, Any]] = {}
    rows_by_index: Dict[int, Dict[str, Any]] = {}
    commands = raw.get("commands", []) if isinstance(raw, dict) else []

    if isinstance(commands, list):
        for index, item in enumerate(commands):
            row = _normalize_timeline_row(item, index)
            rows.append(row)
            rows_by_id[row["step_id"]] = row
            rows_by_index[row["step_index"]] = row

    events = _pick_trajectory_events(raw) if isinstance(raw, dict) else []
    if events:
        for index, item in enumerate(events):
            event_row = _normalize_timeline_row(item, index)
            existing = rows_by_id.get(event_row["step_id"]) or rows_by_index.get(event_row["step_index"])
            if existing is None:
                rows.append(event_row)
                rows_by_id[event_row["step_id"]] = event_row
                rows_by_index[event_row["step_index"]] = event_row
                continue
            _merge_timeline_rows(existing, event_row)

    if not rows and fallback_history:
        for index, item in enumerate(fallback_history):
            rows.append(_normalize_timeline_row(item, index))

    rows = _sort_timeline_rows(rows)
    if not rows:
        return None

    recent_command_row = next((row for row in reversed(rows) if row.get("command")), None)
    recent_publish_row = next(
        (row for row in reversed(rows) if row.get("publish_reason") or row.get("bundle_id")),
        None,
    )

    step_count = _coalesce(
        raw.get("step_count") if isinstance(raw, dict) else None,
        len(commands) if isinstance(commands, list) and commands else None,
        len(rows),
    )
    published_bundles = sum(1 for row in rows if row.get("bundle_id"))
    return {
        "protocol": raw.get("protocol") or raw.get("protocol_version") if isinstance(raw, dict) else None,
        "step_count": step_count,
        "current_step_id": _coalesce(
            raw.get("current_step_id") if isinstance(raw, dict) else None,
            recent_publish_row.get("step_id") if recent_publish_row else None,
            recent_command_row.get("step_id") if recent_command_row else None,
        ),
        "published_bundle_count": published_bundles,
        "recent_command": _coalesce(
            raw.get("latest_command") if isinstance(raw, dict) else None,
            recent_command_row.get("command") if recent_command_row else None,
        ),
        "recent_publish_reason": _coalesce(
            raw.get("latest_publish_reason") if isinstance(raw, dict) else None,
            recent_publish_row.get("publish_reason") if recent_publish_row else None,
        ),
        "recent_bundle_id": recent_publish_row.get("bundle_id") if recent_publish_row else None,
        "entries": rows,
    }


def _load_trajectory(base_dir: Path, *payloads: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    for ref in _trajectory_candidate_refs(base_dir, *payloads):
        candidate = _resolve_ref_path(base_dir, ref)
        if candidate.is_file():
            raw = _read_json(candidate)
            normalized = _normalize_trajectory(raw)
            if normalized is not None:
                normalized["mode"] = "trajectory"
                normalized["source_path"] = str(candidate)
                normalized["source_label"] = os.path.relpath(candidate, base_dir)
                return normalized

    for payload in payloads:
        if not isinstance(payload, dict):
            continue
        for kind, value, label in _iter_trajectory_hints(payload):
            if kind != "object" or not isinstance(value, dict):
                continue
            normalized = _normalize_trajectory(value)
            if normalized is not None:
                normalized["mode"] = "trajectory"
                normalized["source_path"] = None
                normalized["source_label"] = label
                return normalized
    return None


def _history_from_session(session: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    history = session.get("history", [])
    if not isinstance(history, list) or not history:
        return None
    normalized = _normalize_trajectory({}, fallback_history=history)
    if normalized is None:
        return None
    source_state = session.get("source_state", {}) if isinstance(session.get("source_state"), dict) else {}
    normalized["mode"] = "legacy-history"
    normalized["source_path"] = None
    normalized["source_label"] = "session.history"
    normalized["current_step_id"] = _coalesce(
        session.get("current_step_id"),
        normalized.get("current_step_id"),
    )
    normalized["recent_command"] = _coalesce(
        session.get("latest_command"),
        normalized.get("recent_command"),
    )
    normalized["recent_publish_reason"] = _coalesce(
        session.get("latest_publish_reason"),
        normalized.get("recent_publish_reason"),
        source_state.get("last_publish_reason"),
    )
    return normalized


def _apply_session_trajectory_metadata(trajectory: Optional[Dict[str, Any]], session: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if trajectory is None:
        return None
    trajectory["protocol"] = _coalesce(
        trajectory.get("protocol"),
        session.get("trajectory_protocol_version"),
    )
    trajectory["step_count"] = _coalesce(
        session.get("trajectory_step_count"),
        trajectory.get("step_count"),
    )
    trajectory["current_step_id"] = _coalesce(
        session.get("current_step_id"),
        trajectory.get("current_step_id"),
    )
    trajectory["recent_command"] = _coalesce(
        session.get("latest_command"),
        trajectory.get("recent_command"),
    )
    trajectory["recent_publish_reason"] = _coalesce(
        session.get("latest_publish_reason"),
        trajectory.get("recent_publish_reason"),
    )
    return trajectory


def _render_trajectory_text_lines(title: str, trajectory: Optional[Dict[str, Any]], *, limit: int = 5) -> List[str]:
    if not trajectory:
        return []
    lines = [
        "",
        title,
        f"  Source: {trajectory.get('source_label') or trajectory.get('mode') or 'unknown'}",
        f"  Steps: {trajectory.get('step_count', 0)}",
        f"  Published bundles: {trajectory.get('published_bundle_count', 0)}",
    ]
    if trajectory.get("current_step_id"):
        lines.append(f"  Current step: {trajectory['current_step_id']}")
    if trajectory.get("recent_command"):
        lines.append(f"  Recent command: {trajectory['recent_command']}")
    if trajectory.get("recent_publish_reason"):
        lines.append(f"  Recent publish: {trajectory['recent_publish_reason']}")
    if trajectory.get("recent_bundle_id"):
        lines.append(f"  Recent bundle: {trajectory['recent_bundle_id']}")
    entries = trajectory.get("entries", [])
    if entries:
        lines.append("  Timeline")
        for entry in entries[-limit:]:
            label = entry.get("step_label") or entry.get("stage_label") or entry.get("step_id") or "step"
            lines.append(f"    - {label}")
            if entry.get("command"):
                lines.append(f"      Command: {entry['command']}")
            if entry.get("publish_reason"):
                lines.append(f"      Publish: {entry['publish_reason']}")
            if entry.get("bundle_id"):
                lines.append(f"      Bundle: {entry['bundle_id']}")
    return lines


def inspect_bundle(bundle_ref: str) -> Dict[str, Any]:
    bundle_dir, manifest, summary = load_bundle(bundle_ref)
    return {
        "bundle_dir": str(bundle_dir),
        "manifest": manifest,
        "summary": summary,
        "artifact_count": len(manifest.get("artifacts", [])),
        "trajectory": _load_trajectory(bundle_dir, manifest, summary),
    }


def inspect_session(session_ref: str) -> Dict[str, Any]:
    session_dir, session = load_session(session_ref)
    current_bundle = None
    try:
        current_bundle = inspect_bundle(str(session_dir / session.get("current_link", "current")))
    except (FileNotFoundError, ValueError):
        current_bundle = None
    trajectory = _load_trajectory(session_dir, session)
    if trajectory is None:
        trajectory = _history_from_session(session)
    trajectory = _apply_session_trajectory_metadata(trajectory, session)
    return {
        "session_dir": str(session_dir),
        "session": session,
        "current_bundle": current_bundle,
        "trajectory": trajectory,
    }


def render_inspect_text(bundle_ref: str) -> str:
    payload = inspect_bundle(bundle_ref)
    bundle_dir = Path(payload["bundle_dir"])
    manifest = payload["manifest"]
    summary = payload["summary"]
    lines = [
        f"Bundle:      {bundle_dir}",
        f"Protocol:    {manifest.get('protocol_version', 'unknown')}",
        f"Software:    {manifest.get('software', 'unknown')}",
        f"Recipe:      {manifest.get('recipe', 'unknown')}",
        f"Kind:        {manifest.get('bundle_kind', 'unknown')}",
        f"Status:      {manifest.get('status', 'unknown')}",
        f"Created:     {manifest.get('created_at', 'unknown')}",
    ]
    source = manifest.get("source", {})
    if source:
        lines.append(
            "Source:      "
            + (
                source.get("project_path")
                or source.get("capture_path")
                or source.get("project_name")
                or "n/a"
            )
        )
        if source.get("project_fingerprint"):
            lines.append(f"Fingerprint: {source['project_fingerprint']}")
        elif source.get("capture_fingerprint"):
            lines.append(f"Fingerprint: {source['capture_fingerprint']}")
    if summary:
        lines.append("")
        lines.append("Summary")
        lines.append(f"  Headline: {summary.get('headline', '(none)')}")
        facts = summary.get("facts", {})
        for key, value in facts.items():
            lines.append(f"  {key}: {value}")
        for warning in summary.get("warnings", []):
            lines.append(f"  Warning: {warning}")
    lines.append("")
    lines.append("Artifacts")
    for artifact in manifest.get("artifacts", []):
        desc = (
            f"  - {artifact.get('artifact_id', '?')} "
            f"[{artifact.get('role', '?')}] {artifact.get('label', '')}"
        )
        desc += f" -> {artifact.get('path', '')}"
        if artifact.get("bytes") is not None:
            desc += f" ({format_bytes(int(artifact['bytes']))})"
        lines.append(desc)
    lines.extend(_render_trajectory_text_lines("Trajectory", payload.get("trajectory")))
    return "\n".join(lines) + "\n"


def render_session_text(session_ref: str) -> str:
    payload = inspect_session(session_ref)
    session_dir = Path(payload["session_dir"])
    session = payload["session"]
    trajectory = payload.get("trajectory")
    lines = [
        f"Live Session: {session_dir}",
        f"Protocol:     {session.get('protocol_version', 'unknown')}",
        f"Software:     {session.get('software', 'unknown')}",
        f"Recipe:       {session.get('recipe', 'unknown')}",
        f"Status:       {session.get('status', 'unknown')}",
        f"Updated:      {session.get('updated_at', 'unknown')}",
        f"Current:      {session.get('current_bundle_id', 'n/a')}",
        f"Project:      {session.get('project_path') or session.get('project_name') or 'n/a'}",
    ]
    if session.get("watch_command"):
        lines.append(f"Watch:        {session['watch_command']}")
    history_title = "History" if trajectory and trajectory.get("mode") == "legacy-history" else "Trajectory"
    lines.extend(_render_trajectory_text_lines(history_title, trajectory))
    if trajectory is None:
        history = session.get("history", [])
        if history:
            lines.append("")
            lines.append("History")
            for item in history:
                lines.append(
                    f"  - {item.get('bundle_id', '?')} "
                    f"[{item.get('status', 'unknown')}] {item.get('created_at', 'unknown')}"
                )
    return "\n".join(lines) + "\n"


def _artifact_href(output_dir: Path, bundle_dir: Path, artifact_path: str) -> str:
    target = (bundle_dir / artifact_path).resolve()
    return os.path.relpath(target, output_dir)


def _render_artifact_card(output_dir: Path, bundle_dir: Path, artifact: Dict[str, Any]) -> str:
    role = html.escape(artifact.get("role", "artifact"))
    label = html.escape(artifact.get("label", artifact.get("artifact_id", "artifact")))
    path_ref = _artifact_href(output_dir, bundle_dir, artifact.get("path", ""))
    media_type = artifact.get("media_type", "")
    size = artifact.get("bytes")
    meta = []
    if artifact.get("width") and artifact.get("height"):
        meta.append(f"{artifact['width']}×{artifact['height']}")
    if artifact.get("duration_s") is not None:
        meta.append(f"{artifact['duration_s']}s")
    if size is not None:
        meta.append(format_bytes(int(size)))
    meta_line = " · ".join(meta)

    if media_type.startswith("image/"):
        body = f'<img src="{html.escape(path_ref)}" alt="{label}" loading="lazy">'
    elif media_type.startswith("video/"):
        body = (
            f'<video controls preload="metadata" src="{html.escape(path_ref)}">'
            "Your browser does not support embedded video."
            "</video>"
        )
    else:
        body = (
            '<div class="artifact-file">'
            f'<a href="{html.escape(path_ref)}">{html.escape(artifact.get("path", ""))}</a>'
            "</div>"
        )

    badge = f'<span class="artifact-role">{role}</span>'
    details = f'<div class="artifact-meta">{html.escape(meta_line)}</div>' if meta_line else ""
    return (
        '<article class="artifact-card">'
        f"{badge}"
        f'<h3>{label}</h3>'
        f"{details}"
        f"{body}"
        "</article>"
    )


def _render_trajectory_html_section(trajectory: Optional[Dict[str, Any]]) -> str:
    if not trajectory:
        return ""

    summary_cards = [
        ("Source", trajectory.get("source_label") or trajectory.get("mode") or "unknown"),
        ("Steps", trajectory.get("step_count", 0)),
        ("Published", trajectory.get("published_bundle_count", 0)),
    ]
    if trajectory.get("recent_publish_reason"):
        summary_cards.append(("Recent publish", trajectory["recent_publish_reason"]))
    elif trajectory.get("recent_bundle_id"):
        summary_cards.append(("Recent bundle", trajectory["recent_bundle_id"]))

    cards_html = "".join(
        f'<div class="fact-card"><span>{html.escape(str(label))}</span><strong>{html.escape(str(value))}</strong></div>'
        for label, value in summary_cards
    )

    items = trajectory.get("entries", [])[-6:]
    items_html = "".join(
        (
            '<article class="trajectory-item">'
            f'<strong>{html.escape(str(item.get("step_label") or item.get("stage_label") or item.get("step_id") or "step"))}</strong>'
            + (
                f'<div class="trajectory-command"><code>{html.escape(str(item["command"]))}</code></div>'
                if item.get("command")
                else ""
            )
            + (
                f'<div class="trajectory-meta">Publish reason: {html.escape(str(item["publish_reason"]))}</div>'
                if item.get("publish_reason")
                else ""
            )
            + (
                f'<div class="trajectory-meta">Bundle: {html.escape(str(item["bundle_id"]))}</div>'
                if item.get("bundle_id")
                else ""
            )
            + "</article>"
        )
        for item in items
    )

    empty_message = '<div class="artifact-file">No step timeline entries yet.</div>'
    return (
        '<section class="section">'
        "<h2>Trajectory</h2>"
        f'<div class="facts">{cards_html}</div>'
        f'<div class="trajectory-list">{items_html or empty_message}</div>'
        "</section>"
    )


def render_html(bundle_ref: str, output_path: str) -> str:
